            $toolResult.contract_exists)
    }
    $md -join "`n" | Set-Content -LiteralPath $mdPath -Encoding UTF8

    Write-Host ''
    Write-Host 'Artifacts written:'
    Write-Host ("- {0}" -f $jsonPath)
    Write-Host ("- {0}" -f $mdPath)
}

if (-not $gatePass) { exit 1 }

