function Assert-Collect {
    param(
        [bool]$Condition,
        [string]$Message,
        [object]$Details = $null
    )
    if ($Condition) {
        Write-Host "[PASS] $Message"
    } else {
        Write-Host "[FAIL] $Message" -ForegroundColor Red
    }
    return [pscustomobject]@{ pass = $Condition; message = $Message; details = $Details }
}

