    Record-Check -Condition ($zhRoute.route_mode -in @("pack_overlay", "confirm_required")) -Message "[ZH] '$($case.Pack)' route mode is invalid: '$($zhRoute.route_mode)'"

    $enTop = [double]$enRoute.ranked[0].score
