        fixture = Join-Path $fixturesDir "managed-stale-fixture.json"
        expected_classifications = @{ managed_stale = 1 }
        expected_candidate_entry_ids = @("vgo-node-stale-42001")
        expect_report_reason = "report_only_mode"
        expect_apply_reason = "fixture_mode_simulation"
    },
    [pscustomobject]@{
        case_id = "managed-completed-alive"
        fixture = Join-Path $fixturesDir "managed-completed-alive-fixture.json"
        expected_classifications = @{ managed_completed_process_alive = 1 }
        expected_candidate_entry_ids = @("vgo-node-completed-43001")
        expect_report_reason = "report_only_mode"
        expect_apply_reason = "fixture_mode_simulation"
    },
    [pscustomobject]@{
        case_id = "external-node-protected"
        fixture = Join-Path $fixturesDir "external-node-protected-fixture.json"
        expected_classifications = @{ external_audit_only = 1 }
        expected_candidate_entry_ids = @()
        expect_report_reason = $null
        expect_apply_reason = $null
    }
)

$results = @()
$caseSummaries = @()

Add-Assertion -Results ([ref]$results) -Condition (Test-Path -LiteralPath $auditScript) -Message "audit governance script exists" -Details $auditScript
Add-Assertion -Results ([ref]$results) -Condition (Test-Path -LiteralPath $cleanupScript) -Message "cleanup governance script exists" -Details $cleanupScript

foreach ($case in $cases) {
    Add-Assertion -Results ([ref]$results) -Condition (Test-Path -LiteralPath $case.fixture) -Message ("fixture exists: {0}" -f $case.case_id) -Details $case.fixture
    if (-not (Test-Path -LiteralPath $case.fixture)) {
        continue
    }

    $audit = Invoke-ParsedScript -Path $auditScript -Parameters @{
        RepoRoot = $repoRoot
        FixturePath = $case.fixture
        OutputDirectory = $artifactsDir
        WriteMarkdown = $true
        PassThru = $true
    }

    $classificationMap = Get-ClassificationMap -Map $audit.payload.summary.classifications
    $candidateEntryIds = Get-StringSet -Values @($audit.payload.rows | Where-Object { $_.cleanup_candidate } | ForEach-Object { $_.entry_id })
    $expectedCandidateEntryIds = Get-StringSet -Values $case.expected_candidate_entry_ids
    $classificationSummary = @($classificationMap.GetEnumerator() | Sort-Object Name | ForEach-Object { "{0}={1}" -f $_.Key, $_.Value }) -join ", "

    Add-Assertion -Results ([ref]$results) -Condition ($audit.payload.case_id -eq $case.case_id) -Message ("audit case id matches fixture: {0}" -f $case.case_id)
    Add-Assertion -Results ([ref]$results) -Condition (Compare-ClassificationMap -Actual $classificationMap -Expected $case.expected_classifications) -Message ("classification map matches expectation: {0}" -f $case.case_id) -Details ("actual={0}" -f $classificationSummary)
    Add-Assertion -Results ([ref]$results) -Condition ((@($candidateEntryIds) -join "|") -eq (@($expectedCandidateEntryIds) -join "|")) -Message ("cleanup candidate set matches expectation: {0}" -f $case.case_id) -Details ("actual={0}" -f ((@($candidateEntryIds) -join ", ")))
    Add-Assertion -Results ([ref]$results) -Condition (@($audit.payload.rows | Where-Object { $_.cleanup_candidate -and $_.ownership -ne "vco-managed" }).Count -eq 0) -Message ("no non-managed cleanup candidates: {0}" -f $case.case_id)
    Add-Assertion -Results ([ref]$results) -Condition (@($audit.payload.rows | Where-Object { $_.ownership -eq "external" -and $_.cleanup_candidate }).Count -eq 0) -Message ("external rows stay audit-only: {0}" -f $case.case_id)

    $caseSummaries += [pscustomobject]@{
        case_id = $case.case_id
        classification_summary = $classificationSummary
        cleanup_candidate_count = @($candidateEntryIds).Count
        audit_artifact = $audit.artifact_path
        markdown_artifact = $audit.markdown_path
    }

    if ($null -ne $case.expect_report_reason) {
        $reportOnly = Invoke-ParsedScript -Path $cleanupScript -Parameters @{
            RepoRoot = $repoRoot
            FixturePath = $case.fixture
            OutputDirectory = $artifactsDir
            PassThru = $true
        }

        Add-Assertion -Results ([ref]$results) -Condition ([bool](-not $reportOnly.payload.apply_requested)) -Message ("cleanup defaults to report-only: {0}" -f $case.case_id)
        Add-Assertion -Results ([ref]$results) -Condition (@($reportOnly.payload.results).Count -eq @($expectedCandidateEntryIds).Count) -Message ("report-only cleanup result count matches candidates: {0}" -f $case.case_id)
        Add-Assertion -Results ([ref]$results) -Condition (@($reportOnly.payload.results | Where-Object { $_.reason -ne $case.expect_report_reason }).Count -eq 0) -Message ("report-only cleanup reason is deterministic: {0}" -f $case.case_id)
        Add-Assertion -Results ([ref]$results) -Condition (@($reportOnly.payload.results | Where-Object { $_.terminated }).Count -eq 0) -Message ("report-only cleanup does not terminate anything: {0}" -f $case.case_id)

        $applySimulated = Invoke-ParsedScript -Path $cleanupScript -Parameters @{
            RepoRoot = $repoRoot
            FixturePath = $case.fixture
            OutputDirectory = $artifactsDir
            Apply = $true
            PassThru = $true
        }

        Add-Assertion -Results ([ref]$results) -Condition ([bool]$applySimulated.payload.apply_requested) -Message ("apply flag is accepted for fixture simulation: {0}" -f $case.case_id)
        Add-Assertion -Results ([ref]$results) -Condition (@($applySimulated.payload.results | Where-Object { -not $_.simulated }).Count -eq 0) -Message ("fixture apply remains simulated: {0}" -f $case.case_id)
        Add-Assertion -Results ([ref]$results) -Condition (@($applySimulated.payload.results | Where-Object { $_.reason -ne $case.expect_apply_reason }).Count -eq 0) -Message ("fixture apply reason is deterministic: {0}" -f $case.case_id)
        Add-Assertion -Results ([ref]$results) -Condition (@($applySimulated.payload.results | Where-Object { $_.terminated }).Count -eq 0) -Message ("fixture apply does not terminate anything: {0}" -f $case.case_id)
    }
}

$failed = @($results | Where-Object { -not $_.passed })
$summary = [pscustomobject]@{
    generated_at = (Get-Date).ToUniversalTime().ToString("o")
    gate_passed = ($failed.Count -eq 0)
    assertion_count = $results.Count
    failure_count = $failed.Count
    case_summaries = $caseSummaries
    results = $results
}

if ($WriteArtifacts -or $true) {
    Write-GateArtifacts -Directory $targetDir -Summary $summary
}

if ($failed.Count -gt 0) {
    throw ("vibe-node-zombie-gate failed with {0} assertion(s)." -f $failed.Count)
}

$summary | ConvertTo-Json -Depth 30

param(
    [string]$TelemetryOutputRel = '',
    [switch]$KeepTelemetry
)

$ErrorActionPreference = "Stop"

function Assert-True {
    param(
        [bool]$Condition,
        [string]$Message
    )

    if ($Condition) {
        Write-Host "[PASS] $Message"
        return $true
    }

    Write-Host "[FAIL] $Message" -ForegroundColor Red
    return $false
}

function Invoke-Route {
    param(
        [string]$Prompt,
        [string]$Grade,
        [string]$TaskType
    )

    $repoRoot = Resolve-Path (Join-Path $PSScriptRoot "..\..")
    $resolver = Join-Path $repoRoot "scripts\router\resolve-pack-route.ps1"
    $json = & $resolver -Prompt $Prompt -Grade $Grade -TaskType $TaskType
    return ($json | ConvertFrom-Json)
}

$repoRoot = Resolve-Path (Join-Path $PSScriptRoot "..\..")
$policyPath = Join-Path $repoRoot "config\observability-policy.json"
$tmpRel = if ([string]::IsNullOrWhiteSpace($TelemetryOutputRel)) { "outputs/verify/tmp-telemetry" } else { $TelemetryOutputRel }
$tmpDir = Join-Path $repoRoot $tmpRel
$originalRaw = Get-Content -LiteralPath $policyPath -Raw -Encoding UTF8
$results = @()

try {
    Write-Host "=== VCO Observability Gate ==="

    $policy = $originalRaw | ConvertFrom-Json
    $policy.enabled = $true
    $policy.mode = "strict"
    $policy.telemetry.output_dir = $tmpRel
    $policy.telemetry.store_prompt_raw = $false
    $policy.telemetry.prompt_excerpt_max_chars = 0
    $policy.telemetry.sample_rates.shadow = 1.0
    $policy.telemetry.sample_rates.soft = 1.0
    $policy.telemetry.sample_rates.strict = 1.0
    $policy.updated = (Get-Date).ToString("yyyy-MM-dd")
    $policy | ConvertTo-Json -Depth 30 | Set-Content -LiteralPath $policyPath -Encoding UTF8

    if (Test-Path -LiteralPath $tmpDir) {
        Remove-Item -LiteralPath $tmpDir -Recurse -Force
    }
    New-Item -ItemType Directory -Path $tmpDir -Force | Out-Null

    $routes = @()
    $routes += Invoke-Route -Prompt "Please optimize CUDA kernel occupancy and shared memory bank conflict in kernels/hgemm.cu." -Grade "L" -TaskType "coding"
    $routes += Invoke-Route -Prompt "请帮我修一个React表单验证bug" -Grade "M" -TaskType "coding"
    $routes += Invoke-Route -Prompt "Design a scalable event-driven system and evaluate trade-offs." -Grade "L" -TaskType "planning"

    $eventFile = Join-Path $tmpDir ("route-events-{0}.jsonl" -f (Get-Date -Format "yyyyMMdd"))
    $results += Assert-True -Condition (Test-Path -LiteralPath $eventFile) -Message "telemetry file exists"

    $events = @()
    if (Test-Path -LiteralPath $eventFile) {
        $lines = Get-Content -LiteralPath $eventFile -Encoding UTF8
        foreach ($line in $lines) {
            if (-not [string]::IsNullOrWhiteSpace($line)) {
                try {
                    $events += ($line | ConvertFrom-Json)
                } catch {
                    $results += Assert-True -Condition $false -Message "event JSON line parses"
                }
            }
        }
    }

    $results += Assert-True -Condition ($events.Count -ge 3) -Message "telemetry event count >= routed samples"

    if ($events.Count -gt 0) {
        $results += Assert-True -Condition (@($events | Where-Object { -not $_.prompt_hash }).Count -eq 0) -Message "events include prompt_hash"
        $results += Assert-True -Condition (@($events | Where-Object { $_.prompt_excerpt }).Count -eq 0) -Message "raw prompt excerpt is disabled"
        $results += Assert-True -Condition (@($events | Where-Object { -not $_.environment_profile_id }).Count -eq 0) -Message "events include environment_profile_id"
        $results += Assert-True -Condition (@($events | Where-Object { -not $_.user_profile_id }).Count -eq 0) -Message "events include user_profile_id"
        $results += Assert-True -Condition (@($events | Where-Object { -not $_.scenario_key }).Count -eq 0) -Message "events include scenario_key"
        $results += Assert-True -Condition (@($events | Where-Object { -not $_.route.route_mode }).Count -eq 0) -Message "events include route core fields"
    }
} finally {
    Set-Content -LiteralPath $policyPath -Value $originalRaw -Encoding UTF8
    if (-not $KeepTelemetry -and (Test-Path -LiteralPath $tmpDir)) {
        Remove-Item -LiteralPath $tmpDir -Recurse -Force
    }
    Write-Host "Restored observability policy to original content."
}

$passCount = @($results | Where-Object { $_ }).Count
$failCount = @($results | Where-Object { -not $_ }).Count
$total = $results.Count

Write-Host ""
Write-Host "=== Summary ==="
Write-Host "Total assertions: $total"
Write-Host "Passed: $passCount"
Write-Host "Failed: $failCount"

if ($failCount -gt 0) {
    exit 1
}

Write-Host "Observability gate passed."
exit 0

param(
    [switch]$WriteArtifacts,
    [string]$OutputDirectory = ''
)

$ErrorActionPreference = 'Stop'
. (Join-Path $PSScriptRoot '..\common\vibe-governance-helpers.ps1')

function Add-Assertion {
    param(
        [System.Collections.Generic.List[object]]$Assertions,
        [bool]$Pass,
        [string]$Message,
        [object]$Details = $null
    )

    $Assertions.Add([pscustomobject]@{
        pass = [bool]$Pass
        message = $Message
        details = $Details
    }) | Out-Null

    $color = if ($Pass) { 'Green' } else { 'Red' }
    $status = if ($Pass) { 'PASS' } else { 'FAIL' }
    Write-Host ('[{0}] {1}' -f $status, $Message) -ForegroundColor $color
}

function Write-GateArtifacts {
    param(
        [string]$RepoRoot,
        [string]$OutputDirectory,
        [psobject]$Artifact
    )

    $dir = if ([string]::IsNullOrWhiteSpace($OutputDirectory)) { Join-Path $RepoRoot 'outputs\verify' } else { $OutputDirectory }
    New-Item -ItemType Directory -Force -Path $dir | Out-Null

    $jsonPath = Join-Path $dir 'vibe-ops-cockpit-gate.json'
    $mdPath = Join-Path $dir 'vibe-ops-cockpit-gate.md'
    Write-VgoUtf8NoBomText -Path $jsonPath -Content ($Artifact | ConvertTo-Json -Depth 100)

    $lines = @(
        '# VCO Ops Cockpit Gate',
        '',
        ('- Gate Result: **{0}**' -f $Artifact.gate_result),
        ('- Repo Root: `{0}`' -f $Artifact.repo_root),
        ('- Failures: {0}' -f $Artifact.summary.failure_count),
        '',
        '## Assertions',
        ''
    )
    foreach ($assertion in $Artifact.assertions) {
        $lines += ('- `{0}` {1}' -f $(if ($assertion.pass) { 'PASS' } else { 'FAIL' }), $assertion.message)
    }
    Write-VgoUtf8NoBomText -Path $mdPath -Content ($lines -join "`n")
}

$context = Get-VgoGovernanceContext -ScriptPath $PSCommandPath -EnforceExecutionContext
$repoRoot = $context.repoRoot
$assertions = [System.Collections.Generic.List[object]]::new()

$requiredPaths = @(
    'docs/ops-cockpit-governance.md',
    'config/ops-cockpit-panel-contract.json',
    'references/ops-cockpit-gap-matrix.md',
    'outputs/dashboard/ops-dashboard.json',
    'outputs/dashboard/ops-dashboard.md'
)
foreach ($relPath in $requiredPaths) {
    $fullPath = Join-Path $repoRoot $relPath
    Add-Assertion -Assertions $assertions -Pass (Test-Path -LiteralPath $fullPath) -Message ('required asset exists: ' + $relPath) -Details $fullPath
}

$keywordChecks = @(
    [pscustomobject]@{ path = 'docs/ops-cockpit-governance.md'; keywords = @(
        'actionable panels',
        'Every panel must produce',
        'ops-dashboard.json',
        'gap matrix'
    ) },
    [pscustomobject]@{ path = 'config/ops-cockpit-panel-contract.json'; keywords = @(
        'freshness',
        'promotion',
        'replay',
        'rollback',
        'release'
    ) },
    [pscustomobject]@{ path = 'references/ops-cockpit-gap-matrix.md'; keywords = @(
        'plane_id',
        'blocker',
        'evidence_ref',
        'next_action'
    ) },
    [pscustomobject]@{ path = 'outputs/dashboard/ops-dashboard.md'; keywords = @(
        'Actionable Panels',
        'Blockers',
        'Evidence',
        'Next Action'
    ) }
)
foreach ($check in $keywordChecks) {
    $targetPath = Join-Path $repoRoot $check.path
    if (-not (Test-Path -LiteralPath $targetPath)) {
        continue
    }
    $raw = Get-Content -LiteralPath $targetPath -Raw -Encoding UTF8
    foreach ($keyword in @($check.keywords)) {
        Add-Assertion -Assertions $assertions -Pass ($raw.Contains($keyword)) -Message ('keyword present in ' + $check.path + ': ' + $keyword) -Details $keyword
    }
}

$contractPath = Join-Path $repoRoot 'config\ops-cockpit-panel-contract.json'
$dashboardJsonPath = Join-Path $repoRoot 'outputs\dashboard\ops-dashboard.json'
if ((Test-Path -LiteralPath $contractPath) -and (Test-Path -LiteralPath $dashboardJsonPath)) {
    $contract = Get-Content -LiteralPath $contractPath -Raw -Encoding UTF8 | ConvertFrom-Json
    $dashboard = Get-Content -LiteralPath $dashboardJsonPath -Raw -Encoding UTF8 | ConvertFrom-Json
    $hasActionablePanels = $dashboard.PSObject.Properties.Name -contains 'actionable_panels'
    Add-Assertion -Assertions $assertions -Pass $hasActionablePanels -Message 'dashboard declares actionable_panels'
    $panels = if ($hasActionablePanels) { @($dashboard.actionable_panels) } else { @() }
    foreach ($panelDef in @($contract.panels)) {
        $panelId = [string]$panelDef.panel_id
        $matchedPanels = @($panels | Where-Object { $_.panel_id -eq $panelId } | Select-Object -First 1)
        $panel = if ($matchedPanels.Count -gt 0) { $matchedPanels[0] } else { $null }
        Add-Assertion -Assertions $assertions -Pass ($null -ne $panel) -Message ('dashboard contains panel: ' + $panelId) -Details $panelId
        if ($null -eq $panel) {
            continue
        }
        foreach ($field in @($panelDef.required_fields)) {
            $hasField = $panel.PSObject.Properties.Name -contains $field
            $value = if ($hasField) { $panel.$field } else { $null }
            $nonEmpty = $false
            if ($hasField) {
                if ($value -is [System.Array]) {
                    $nonEmpty = @($value).Count -gt 0
                } else {
                    $nonEmpty = -not [string]::IsNullOrWhiteSpace([string]$value)
                }
            }
            Add-Assertion -Assertions $assertions -Pass ($hasField -and $nonEmpty) -Message ('panel {0} provides field {1}' -f $panelId, $field) -Details $value
        }
    }
}

$failureCount = @($assertions | Where-Object { -not $_.pass }).Count
$gateResult = if ($failureCount -eq 0) { 'PASS' } else { 'FAIL' }
$artifact = [pscustomobject]@{
    gate = 'vibe-ops-cockpit-gate'
    repo_root = $repoRoot
    gate_result = $gateResult
    generated_at = (Get-Date).ToString('s')
    assertions = @($assertions)
    summary = [ordered]@{
        total = $assertions.Count
        failure_count = $failureCount
    }
}

if ($WriteArtifacts) {
    Write-GateArtifacts -RepoRoot $repoRoot -OutputDirectory $OutputDirectory -Artifact $artifact
}

if ($failureCount -gt 0) {
    exit 1
}

param()

