$skillMd = Get-Content -LiteralPath (Join-Path $repoRoot "SKILL.md") -Raw -Encoding UTF8
$runtimeProtocol = Get-Content -LiteralPath (Join-Path $repoRoot "protocols\runtime.md") -Raw -Encoding UTF8

